/**
 * Simplified CSV Parser for Widget Adressage
 * A lightweight alternative to Papa Parse for basic CSV parsing needs
 * Handles quoted fields, commas in quoted strings, and various CSV formats
 */
(function(global) {
    'use strict';
    
    const Papa = {
        parse: function(input, config) {
            config = config || {};
            
            // Handle File input
            if (input instanceof File) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    const csvString = e.target.result;
                    const result = parseCSVString(csvString, config);
                    if (config.complete) {
                        config.complete(result);
                    }
                };
                reader.onerror = function() {
                    if (config.error) {
                        config.error(new Error('Failed to read file'));
                    }
                };
                reader.readAsText(input, config.encoding || 'UTF-8');
                return;
            }
            
            // Handle string input
            if (typeof input === 'string') {
                return parseCSVString(input, config);
            }
            
            throw new Error('Invalid input type. Expected File or string.');
        }
    };
    
    function parseCSVString(csvString, config) {
        const delimiter = config.delimiter || ',';
        const newline = config.newline || '\n';
        const header = config.header !== false;
        const skipEmptyLines = config.skipEmptyLines !== false;
        
        try {
            const rows = parseCSV(csvString, delimiter, newline, skipEmptyLines);
            
            if (rows.length === 0) {
                return { data: [], errors: [], meta: { fields: [] } };
            }
            
            let data, fields;
            
            if (header) {
                fields = rows[0];
                data = rows.slice(1).map(row => {
                    const obj = {};
                    fields.forEach((field, index) => {
                        obj[field] = row[index] || '';
                    });
                    return obj;
                });
            } else {
                fields = [];
                data = rows;
            }
            
            return {
                data: data,
                errors: [],
                meta: {
                    fields: fields,
                    delimiter: delimiter
                }
            };
        } catch (error) {
            return {
                data: [],
                errors: [{ message: error.message }],
                meta: { fields: [] }
            };
        }
    }
    
    function parseCSV(text, delimiter, newline, skipEmptyLines) {
        const rows = [];
        let currentRow = [];
        let currentField = '';
        let inQuotes = false;
        let i = 0;
        
        // Normalize line endings
        text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
        
        while (i < text.length) {
            const char = text[i];
            const nextChar = text[i + 1];
            
            if (inQuotes) {
                if (char === '"') {
                    if (nextChar === '"') {
                        // Escaped quote
                        currentField += '"';
                        i += 2;
                        continue;
                    } else {
                        // End of quoted field
                        inQuotes = false;
                        i++;
                        continue;
                    }
                } else {
                    currentField += char;
                    i++;
                }
            } else {
                if (char === '"') {
                    // Start of quoted field
                    inQuotes = true;
                    i++;
                } else if (char === delimiter) {
                    // End of field
                    currentRow.push(currentField.trim());
                    currentField = '';
                    i++;
                } else if (char === '\n') {
                    // End of row
                    currentRow.push(currentField.trim());
                    
                    if (!skipEmptyLines || currentRow.some(f => f !== '')) {
                        rows.push(currentRow);
                    }
                    
                    currentRow = [];
                    currentField = '';
                    i++;
                } else {
                    currentField += char;
                    i++;
                }
            }
        }
        
        // Push last field and row if exists
        if (currentField !== '' || currentRow.length > 0) {
            currentRow.push(currentField.trim());
            if (!skipEmptyLines || currentRow.some(f => f !== '')) {
                rows.push(currentRow);
            }
        }
        
        return rows;
    }
    
    // Export to global scope
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = Papa;
    } else {
        global.Papa = Papa;
    }
    
})(typeof window !== 'undefined' ? window : this);
